#include <stdio.h>
int main(void) {
    int n, value, largest;
    if (scanf("%d", &n) != 1 || n < 1) return 0;
    scanf("%d", &largest);
    for (int i = 1; i < n; i++) {
        scanf("%d", &value);
        if (value > largest) largest = value;
    }
    printf("%d\n", largest);
    return 0;
}

